function escapeRegex(s){return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");}function matchCase(original, replacement){if (original.length > 1 && original === original.toUpperCase()) return replacement.toUpperCase();if (original[0] === original[0].toUpperCase()) return replacement.charAt(0).toUpperCase() + replacement.slice(1);return replacement;}function applyDictionary(text, phrases, words){let result = text;const sortedPhrases = [...phrases].sort((a, b) => b[0].length - a[0].length);for (const [from, to] of sortedPhrases){result = result.replace(new RegExp("\\b" + escapeRegex(from) + "\\b", "gi"), (m) => matchCase(m, to));}result = result.replace(/[A-Za-z']+/g, (word) =>{const hit = words[word.toLowerCase()];return hit ? matchCase(word, hit) : word;});return result;}const SHAKESPEAREAN_PHRASES = [ ["you are", "thou art"], ["you have", "thou hast"], ["you will", "thou shalt"], ["you would", "thou wouldst"], ["do not", "dost not"], ["does not", "doth not"], ["did not", "didst not"], ["is not", "is not"], ["good bye", "fare thee well"], ];const SHAKESPEAREAN_WORDS ={you: "thou", your: "thy", yours: "thine", yourself: "thyself", hello: "hail", hi: "hail", friend: "good fellow", friends: "good fellows", yes: "aye", no: "nay", very: "most", really: "verily", before: "ere", because: "for that", if: "an", also: "likewise", soon: "anon", now: "presently", listen: "hark", stop: "cease", again: "once more", man: "sirrah", know: "doth know", knows: "knoweth", says: "sayeth", said: "spake",};const PIRATE_PHRASES = [ ["hello there", "ahoy there"], ["excuse me", "avast"], ["my friend", "me matey"], ["is not", "ain't"], ];const PIRATE_WORDS ={hello: "ahoy", hi: "ahoy", hey: "arr", yes: "aye", my: "me", your: "yer", you: "ye", is: "be", are: "be", am: "be", the: "th'", friend: "matey", friends: "mateys", money: "doubloons", drink: "grog", stop: "avast", sir: "cap'n", boy: "lad", girl: "lass", old: "ol'", here: "here", bathroom: "head", toilet: "head", crazy: "mad as a sack o' weasels", understand: "savvy", ok: "aye aye", okay: "aye aye", stranger: "landlubber",};const CORPORATE_PHRASES = [ ["let's talk", "let's circle back"], ["talk later", "circle back offline"], ["figure out", "ideate on"], ["good idea", "actionable insight"], ["work together", "synergize"], ["think about", "ideate on"], ["plan to", "aim to action"], ["as soon as possible", "with urgency, in the near-term"], ];const CORPORATE_WORDS ={problem: "challenge", meeting: "touchpoint", plan: "roadmap", team: "cross-functional pod", help: "enablement", use: "leverage", soon: "in the near-term", now: "in real-time", important: "mission-critical", good: "best-in-class", talk: "sync", call: "touch base", agree: "align", start: "kick off", finish: "close the loop on", idea: "insight", goal: "north star", update: "sync-up", change: "pivot", improve: "optimize", discuss: "unpack", review: "circle back on", question: "action item",};function yeOldify(word){const lower = word.toLowerCase();const map ={the: "ye", you: "thee", your: "thy", is: "is", was: "wast", of: "of"};if (map[lower]) return matchCase(word, map[lower]);let out = word;if (/^f/i.test(out) && out.length > 2) out = out[0] + out[0] + out.slice(1); if (/[bcdfgklmnprstvz]$/i.test(out) && out.length >= 4 && !/e$/i.test(out)) out = out + "e";return out;}function applyYeOlde(text){return text.replace(/[A-Za-z']+/g, yeOldify);}const DIALECTS ={shakespearean: (t) => applyDictionary(t, SHAKESPEAREAN_PHRASES, SHAKESPEAREAN_WORDS), pirate: (t) => applyDictionary(t, PIRATE_PHRASES, PIRATE_WORDS), corporate: (t) => applyDictionary(t, CORPORATE_PHRASES, CORPORATE_WORDS), yeolde: applyYeOlde,};function executeDialectDeck(){const raw = document.getElementById("dialect-input").value;const style = document.getElementById("dialect-style").value;const out = document.getElementById("dialect-result");if (!raw.trim()){GAMA.say("idle");out.textContent = "";return;}out.textContent = DIALECTS[style](raw);GAMA.say("success");}